# Generate prediction for test input based on discovered patterns

def analyze_l_tromino_orientation(piece_cells):
    """Analyze L-tromino and determine which diagonal(s) it spawns"""

    coords = [(r,c) for r,c in piece_cells]
    r_min, r_max = min(c[0] for c in coords), max(c[0] for c in coords)
    c_min, c_max = min(c[1] for c in coords), max(c[1] for c in coords)

    # Determine full 2x2 square and which corner is missing
    full_corners = {(r_min, c_min), (r_min, c_max), (r_max, c_min), (r_max, c_max)}
    set_coords = set(coords)
    missing = list(full_corners - set_coords)[0]

    # Determine orientation
    if missing == (r_min, c_min):
        diag_type = "main"
    elif missing == (r_max, c_max):
        diag_type = "main"
    elif missing == (r_min, c_max):
        diag_type = "anti"
    else:
        diag_type = "anti"

    if diag_type == "main":
        d_const = coords[0][1] - coords[0][0]
        trail_dir = "down-right"
    else:
        s_const = coords[0][0] + coords[0][1]
        if missing == (r_min, c_max):
            trail_dir = "down-left"
        else:
            trail_dir = "up-right"

    return {
        "missing": missing,
        "diag_type": diag_type,
        "d_const": d_const if diag_type == "main" else None,
        "s_const": s_const if diag_type != "main" else None,
        "trail_dir": trail_dir
    }

